// LPE Cosmetic Layer Attachment Preview
class CosmeticPreviewScene extends Phaser.Scene {
    create() {
        const aura = this.add.sprite(400, 300, 'aura_layer');
        this.tweens.add({
            targets: aura,
            alpha: { from: 0.4, to: 1.0 },
            duration: 800,
            yoyo: true,
            repeat: -1
        });
    }
}

